{"status":"candidate","chosen_option":"component_traversal","assumptions":[],"observations":[{"statement":"A connected component has two complementary valid assignments, so compare the aggregate costs for each orientation and add the smaller.","source_ids":["task"]},{"statement":"Self-loops and duplicate constraints are handled by checking every labeled edge during traversal; a conflicting required bit makes the system impossible.","source_ids":["task"]}],"artifact":{"code":"import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    costs = data[2:2 + n]
    graph = [[] for _ in range(n)]
    pos = 2 + n
    for _ in range(m):
        u, v, p = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        graph[u].append((v, p))
        graph[v].append((u, p))

    bits = [-1] * n
    answer = 0
    for start in range(n):
        if bits[start] != -1:
            continue
        bits[start] = 0
        stack = [start]
        zero_cost = one_cost = 0
        while stack:
            u = stack.pop()
            if bits[u] == 1:
                one_cost += costs[u]
            else:
                zero_cost += costs[u]
            for v, parity in graph[u]:
                required = bits[u] ^ parity
                if bits[v] == -1:
                    bits[v] = required
                    stack.append(v)
                elif bits[v] != required:
                    print('IMPOSSIBLE')
                    return
        answer += min(zero_cost, one_cost)

    print(answer)


if __name__ == '__main__':
    main()
